// Generated by engr-toolbox. Edit the canonical .agents/ source, then run sync. Delete this line to own the file.
import fs from 'node:fs';
import path from 'node:path';
import { loadTickets } from './tickets.mjs';

export const CRITERION_REF = /\b([a-z0-9][a-z0-9-]*\/\d{2,3}#AC\d+)\b/gi;
const QA_DIR = 'qa';
const HISTORY = path.join(QA_DIR, 'runs', 'history.json');
const SKIP_DIRS = new Set(['.git', 'node_modules', 'tickets', 'docs', '.agents', '.ai', '.claude', '.cursor', '.codex', '.opencode', '.windsurf', '.clinerules', '.kilo', '.openhands', 'dist', 'build', 'coverage', 'out', 'target', 'vendor']);
const TEXT_EXT = /\.(m?[jt]sx?|cjs|py|rb|go|java|kt|cs|php|rs|swift|feature|robot|ya?ml|json)$/i;

export function hasQa(root) {
  return fs.existsSync(path.join(root, QA_DIR));
}

const refsIn = text => [...new Set([...text.matchAll(CRITERION_REF)].map(m => m[1].replace(/#ac/i, '#AC')))];

// ---------- JUnit ----------

function attr(tag, name) {
  const m = tag.match(new RegExp(`\\b${name}\\s*=\\s*"([^"]*)"`));
  return m ? decode(m[1]) : '';
}

function decode(s) {
  return s.replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&quot;/g, '"').replace(/&apos;/g, "'").replace(/&amp;/g, '&');
}

/** Parse JUnit XML (one file's text) into test cases. Tolerant of the common runner dialects. */
export function parseJUnit(xml) {
  const cases = [];
  const re = /<testcase\b([^>]*?)(\/>|>([\s\S]*?)<\/testcase>)/g;
  let m;
  while ((m = re.exec(xml))) {
    const open = `<testcase ${m[1]}>`;
    const body = m[3] || '';
    let outcome = 'passed';
    let message = '';
    const fail = body.match(/<(failure|error)\b([^>]*)>?/);
    if (fail) {
      outcome = 'failed';
      message = attr(fail[0], 'message');
    } else if (/<skipped\b/.test(body)) {
      outcome = 'skipped';
    }
    const name = attr(open, 'name');
    const classname = attr(open, 'classname');
    cases.push({
      id: classname ? `${classname} › ${name}` : name,
      name,
      classname,
      time: Number(attr(open, 'time')) || 0,
      outcome,
      message,
      criteria: refsIn(`${classname} ${name}`)
    });
  }
  return cases;
}

export function readJUnit(target) {
  const files = [];
  const stat = fs.statSync(target);
  if (stat.isDirectory()) {
    const walk = dir => {
      for (const e of fs.readdirSync(dir, { withFileTypes: true })) {
        const p = path.join(dir, e.name);
        if (e.isDirectory()) walk(p);
        else if (e.name.endsWith('.xml')) files.push(p);
      }
    };
    walk(target);
  } else files.push(target);
  if (!files.length) throw new Error(`No JUnit XML files found at ${target}`);
  return files.flatMap(f => parseJUnit(fs.readFileSync(f, 'utf8')));
}

export function summarise(cases) {
  const count = o => cases.filter(c => c.outcome === o).length;
  return { total: cases.length, passed: count('passed'), failed: count('failed'), skipped: count('skipped') };
}

// ---------- history and flaky ----------

export function loadHistory(root) {
  const p = path.join(root, HISTORY);
  return fs.existsSync(p) ? JSON.parse(fs.readFileSync(p, 'utf8')) : { runs: [] };
}

export function recordRun(root, { cases, feature = null, ticket = null, label = null, date = new Date(), commit = null }) {
  const history = loadHistory(root);
  const run = {
    at: date.toISOString(),
    feature,
    ticket,
    label,
    commit,
    summary: summarise(cases),
    results: Object.fromEntries(cases.map(c => [c.id, c.outcome])),
    criteria: Object.fromEntries(
      [...new Set(cases.flatMap(c => c.criteria))].map(ref => {
        const outcomes = cases.filter(c => c.criteria.includes(ref)).map(c => c.outcome);
        return [ref, outcomes.includes('failed') ? 'failed' : outcomes.every(o => o === 'skipped') ? 'skipped' : 'passed'];
      })
    )
  };
  history.runs.push(run);
  const p = path.join(root, HISTORY);
  fs.mkdirSync(path.dirname(p), { recursive: true });
  fs.writeFileSync(p, JSON.stringify(history, null, 2) + '\n', 'utf8');
  return run;
}

/** A test is flaky when it both passed and failed within the last `window` runs that included it. */
export function findFlaky(history, window = 10) {
  const seen = new Map();
  for (const run of history.runs.slice(-window)) {
    for (const [id, outcome] of Object.entries(run.results)) {
      if (outcome === 'skipped') continue;
      if (!seen.has(id)) seen.set(id, { passed: 0, failed: 0 });
      seen.get(id)[outcome] += 1;
    }
  }
  return [...seen.entries()]
    .filter(([, c]) => c.passed > 0 && c.failed > 0)
    .map(([id, c]) => ({ id, ...c, rate: c.failed / (c.passed + c.failed) }))
    .sort((a, b) => b.rate - a.rate);
}

export function writeFlaky(root, flaky) {
  const lines = ['# Flaky Tests', '', '_Generated by `test-report --junit`. Tests that both passed and failed in the last 10 runs. Fix with the `fix-flaky-tests` skill._', ''];
  if (!flaky.length) lines.push('None.');
  else {
    lines.push('| Test | Passed | Failed | Failure rate |', '|---|---|---|---|');
    for (const f of flaky) lines.push(`| ${f.id} | ${f.passed} | ${f.failed} | ${Math.round(f.rate * 100)}% |`);
  }
  const p = path.join(root, QA_DIR, 'flaky.md');
  fs.mkdirSync(path.dirname(p), { recursive: true });
  fs.writeFileSync(p, lines.join('\n') + '\n', 'utf8');
  return p;
}

export function writeRunSummary(root, run, cases) {
  const day = run.at.slice(0, 10);
  const name = [day, run.feature || 'all', run.label || 'automated'].join('-').replace(/[^a-z0-9.-]+/gi, '-');
  const p = path.join(root, QA_DIR, 'runs', `${name}.md`);
  const s = run.summary;
  const lines = [
    `# Automated run: ${run.feature || 'all features'}${run.label ? ` (${run.label})` : ''}`,
    '',
    `**Date:** ${day}`,
    run.commit ? `**Build:** ${run.commit}` : null,
    run.ticket ? `**Ticket:** ${run.ticket}` : null,
    '',
    `Passed ${s.passed} · Failed ${s.failed} · Skipped ${s.skipped} · Total ${s.total}`,
    ''
  ].filter(l => l !== null);
  const failed = cases.filter(c => c.outcome === 'failed');
  if (failed.length) {
    lines.push('## Failures', '', '| Test | Criteria | Message |', '|---|---|---|');
    for (const c of failed) lines.push(`| ${c.id} | ${c.criteria.join(', ') || '-'} | ${c.message.replace(/\|/g, '\\|').slice(0, 160)} |`);
    lines.push('');
  }
  fs.mkdirSync(path.dirname(p), { recursive: true });
  fs.writeFileSync(p, lines.join('\n') + '\n', 'utf8');
  return p;
}

export function lastRunFor(history, feature) {
  const runs = history.runs.filter(r => !feature || r.feature === feature);
  return runs.length ? runs[runs.length - 1] : null;
}

// ---------- traceability ----------

function headerField(content, label) {
  const m = content.match(new RegExp(`^\\*{0,2}${label}:\\*{0,2}\\s*(.*?)\\s*$`, 'mi'));
  return m ? m[1].trim() : '';
}

export function loadManualCases(root) {
  const dir = path.join(root, QA_DIR, 'cases');
  const cases = [];
  if (!fs.existsSync(dir)) return cases;
  const walk = d => {
    for (const e of fs.readdirSync(d, { withFileTypes: true })) {
      const p = path.join(d, e.name);
      if (e.isDirectory()) walk(p);
      else if (/^TC-.*\.md$/i.test(e.name)) {
        const content = fs.readFileSync(p, 'utf8');
        const id = (e.name.match(/^(TC-[A-Za-z0-9]+)/i) || [])[1];
        cases.push({ id, file: path.relative(root, p).split(path.sep).join('/'), covers: refsIn(headerField(content, 'Covers')), priority: headerField(content, 'Priority') });
      }
    }
  };
  walk(dir);
  return cases;
}

/** Latest manual result per case id, from `| Case | Covers | Result |` tables in qa/runs/*.md (files sorted by name = date). */
export function loadManualResults(root) {
  const dir = path.join(root, QA_DIR, 'runs');
  const results = new Map();
  if (!fs.existsSync(dir)) return results;
  for (const f of fs.readdirSync(dir).filter(x => x.endsWith('.md') && x !== 'README.md').sort()) {
    const lines = fs.readFileSync(path.join(dir, f), 'utf8').split(/\r?\n/);
    let cols = null;
    for (const line of lines) {
      if (!line.trim().startsWith('|')) {
        cols = null;
        continue;
      }
      const cells = line.split('|').slice(1, -1).map(c => c.trim());
      if (!cols) {
        const lower = cells.map(c => c.toLowerCase());
        if (lower.includes('case') && lower.includes('result')) cols = { caseIdx: lower.indexOf('case'), resultIdx: lower.indexOf('result') };
        continue;
      }
      if (cells.every(c => /^:?-+:?$/.test(c))) continue;
      const id = (cells[cols.caseIdx] || '').match(/TC-[A-Za-z0-9]+/i)?.[0];
      const result = (cells[cols.resultIdx] || '').toLowerCase();
      if (id && ['pass', 'fail', 'blocked', 'not-run'].includes(result)) results.set(id.toUpperCase(), { result, run: f });
    }
  }
  return results;
}

/** Automated tests referencing criteria, found by scanning test-like source files. */
export function scanAutomatedRefs(root) {
  const refs = new Map();
  const walk = dir => {
    for (const e of fs.readdirSync(dir, { withFileTypes: true })) {
      if (e.isDirectory()) {
        if (SKIP_DIRS.has(e.name) || (dir === root && e.name === QA_DIR)) continue;
        walk(path.join(dir, e.name));
      } else if (TEXT_EXT.test(e.name)) {
        const p = path.join(dir, e.name);
        if (fs.statSync(p).size > 1_000_000) continue;
        const rel = path.relative(root, p).split(path.sep).join('/');
        for (const ref of refsIn(fs.readFileSync(p, 'utf8'))) {
          if (!refs.has(ref)) refs.set(ref, new Set());
          refs.get(ref).add(rel);
        }
      }
    }
  };
  walk(root);
  return refs;
}

export function buildTrace(root, { feature = null } = {}) {
  const tickets = loadTickets(root).filter(t => (!feature || t.feature === feature) && ['dev', 'bug'].includes(t.type) && t.status !== 'wontfix');
  const manual = loadManualCases(root);
  const manualResults = loadManualResults(root);
  const automated = scanAutomatedRefs(root);
  const last = lastRunFor(loadHistory(root), feature);
  const rows = [];
  for (const t of tickets) {
    for (const c of t.criteria) {
      const cases = manual.filter(m => m.covers.includes(c.id));
      const tests = [...(automated.get(c.id) || [])];
      const manualOutcomes = cases.map(m => manualResults.get(String(m.id).toUpperCase())?.result).filter(Boolean);
      rows.push({
        criterion: c.id,
        ticket: t.id,
        text: c.text,
        manual: cases.map(m => m.id),
        automated: tests,
        automatedResult: last?.criteria?.[c.id] || null,
        manualResult: manualOutcomes.includes('fail') ? 'fail' : manualOutcomes.includes('blocked') ? 'blocked' : manualOutcomes.length && manualOutcomes.every(o => o === 'pass') ? 'pass' : manualOutcomes.length ? 'not-run' : null,
        covered: cases.length > 0 || tests.length > 0
      });
    }
  }
  const covered = rows.filter(r => r.covered).length;
  return { feature, rows, total: rows.length, covered, uncovered: rows.filter(r => !r.covered) };
}

export function renderTrace(trace) {
  const lines = ['# Traceability', '', '_Generated by `trace --write`. Criterion → manual cases → automated tests → latest results._', ''];
  lines.push(`Covered: ${trace.covered}/${trace.total}${trace.feature ? ` (feature ${trace.feature})` : ''}`, '');
  if (!trace.rows.length) {
    lines.push('No acceptance criteria found on dev or bug tickets.');
    return lines.join('\n');
  }
  lines.push('| Criterion | Text | Manual cases | Manual result | Automated tests | Automated result |', '|---|---|---|---|---|---|');
  for (const r of trace.rows) {
    lines.push(`| ${r.criterion} | ${r.text.replace(/\|/g, '\\|')} | ${r.manual.join(', ') || '-'} | ${r.manualResult || '-'} | ${r.automated.join('<br>') || '-'} | ${r.automatedResult || '-'} |`);
  }
  return lines.join('\n');
}

export function writeTrace(root, trace) {
  const p = path.join(root, QA_DIR, 'traceability.md');
  fs.mkdirSync(path.dirname(p), { recursive: true });
  fs.writeFileSync(p, renderTrace(trace) + '\n', 'utf8');
  return p;
}

export function formatTrace(trace) {
  const out = [`Criteria covered: ${trace.covered}/${trace.total}`];
  for (const r of trace.rows) {
    const mark = r.covered ? '✔' : '✖';
    const bits = [];
    if (r.manual.length) bits.push(`manual ${r.manual.join(',')}${r.manualResult ? ` (${r.manualResult})` : ''}`);
    if (r.automated.length) bits.push(`auto ${r.automated.length} file(s)${r.automatedResult ? ` (${r.automatedResult})` : ''}`);
    out.push(`  ${mark} ${r.criterion.padEnd(22)} ${bits.join(' · ') || 'not covered'}`);
  }
  return out.join('\n');
}
